const rnd=sd=>{let v=sd+1;return()=>{v=(v*16807)%2147483647;return v/2147483647}};
function genW(sd){const k=wg.l,per=SE[k]*(45+RS[k])/60,n=Math.max(2,Math.round(Math.max(6,wg.m-8)/per)),R=rnd(sd),sh=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(R()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a},all=X.map((x,i)=>i);
const pool=WA[wg.g].map(a=>sh(all.filter(i=>X[i][1]===a))),ids=[];let j=0;
while(ids.length<n&&pool.some(p=>p.length)){const p=pool[j%pool.length];if(p.length)ids.push(p.shift());j++}
if(ids.length<n){const rest=sh(all.filter(i=>!ids.includes(i)&&X[i][1]!=="Mobility"));while(ids.length<n&&rest.length)ids.push(rest.shift())}
return{g:wg.g,l:k,m:wg.m,ids}}
