$("#wo").innerHTML=`<div class="book" style="margin-top:22px;animation:fi .5s"><h3>Your ${WG[w.g].toLowerCase()} workout${sv?" (saved)":""}</h3><p class="mut" style="margin:6px 0 16px">${w.ids.length} exercises · about ${tot} min · ${L3[k]} level</p><b>Warm-up (about 4 min)</b>${["Arm Circles","Running in Place","Cat-Cow"].map(nmI).map(i=>row(i,"45 seconds, easy pace")).join("")}<b style="display:block;margin-top:16px">Main workout</b>${w.ids.map((i,n)=>row(i,`${n+1}. ${dose(X[i],k)}${X[i][2]==="min"?"":" · rest "+RS[k]+" sec"}`)).join("")}<b style="display:block;margin-top:16px">Cool-down (about 4 min)</b>${["Standing Quad Stretch","Forward Fold","Child’s Pose"].map(nmI).map(i=>row(i,"30 seconds, slow breathing")).join("")}<div class="mf"><button class="btn" id="wrg">Regenerate</button><button class="btn o" id="wsv">Save workout</button></div><p class="mut" style="font-size:.84rem;margin-top:14px">Tap any exercise to watch the demo and see the steps. Stop if you feel sharp pain, and consult a professional if you have an injury or medical condition.</p></div>`;
