let reps=0;
/* Hero: dumbbell curl. The body is one still, transparent image (hero/body.webp). Only the two arm layers
   (forearm + hand + dumbbell, hero/L-xx and R-xx) move, and the dumbbell stays rigid, so it never bends or gets cut.
   The old photo backdrop is removed, so the hero section's own background shows behind the man. */
(function(){
const lift=$(".lift"),cv=$(".lf-canvas"),repsEl=$("#reps"),badge=$(".lf-rep");
if(!lift||!cv)return;
const ctx=cv.getContext("2d"),K=53,BODY=[160,16],SPR={L:[8,260],R:[488,260]};
const UP=500,HOLD_TOP=40,DOWN=600,HOLD_LOW=40,CYCLE=UP+HOLD_TOP+DOWN+HOLD_LOW; /* ms: fast rep */
const ease=x=>(1-Math.cos(Math.PI*x))/2;
const still=matchMedia("(prefers-reduced-motion: reduce)").matches;
const body=new Image(),L=[],R=[];let loaded=0,running=false,raf=0,t0=0,last=-1,counted=false;const TOTAL=1+K*2;
function rep(){reps=reps>=999?1:reps+1;if(repsEl)repsEl.textContent=reps;if(badge){badge.classList.remove("rep-hit");void badge.offsetWidth;badge.classList.add("rep-hit");setTimeout(()=>badge.classList.remove("rep-hit"),600)}}
function pos(ms){const t=ms%CYCLE;
 if(t<UP)return[ease(t/UP),0];
 if(t<UP+HOLD_TOP)return[1,1];
 if(t<UP+HOLD_TOP+DOWN)return[1-ease((t-UP-HOLD_TOP)/DOWN),2];
 return[0,3]}
function draw(p){const i=Math.round(p*(K-1));if(i===last)return;last=i;
 ctx.clearRect(0,0,cv.width,cv.height);ctx.drawImage(body,BODY[0],BODY[1]);
 ctx.drawImage(L[i],SPR.L[0],SPR.L[1]);ctx.drawImage(R[i],SPR.R[0],SPR.R[1])}
function frame(now){if(!running)return;const r=pos(now-t0);draw(r[0]);
 if(r[1]===1&&!counted){counted=true;rep()}if(r[1]!==1)counted=false;raf=requestAnimationFrame(frame)}
function start(){if(running||still||document.hidden||loaded<TOTAL)return;running=true;t0=performance.now();raf=requestAnimationFrame(frame)}
function stop(){running=false;cancelAnimationFrame(raf)}
function done(){if(++loaded===TOTAL){draw(0);lift.classList.add("ready");start()}}
function ld(im,src){im.decoding="async";im.onload=done;im.src=src;return im}
ld(body,"hero/body.webp");
for(let i=0;i<K;i++){const n=String(i).padStart(2,"0");L.push(ld(new Image(),"hero/L-"+n+".webp"));R.push(ld(new Image(),"hero/R-"+n+".webp"))}
new IntersectionObserver(es=>es.forEach(e=>e.isIntersecting?start():stop()),{threshold:.1}).observe(lift);
document.addEventListener("visibilitychange",()=>{document.hidden?stop():start()});
})();
